import { DigoAsset } from '@digo-org/digo-api';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  override render() {
    // Transform time series data: map timeArray to chart data points
    const chartData = this.timeArray?.map((timeLabel, timeIndex) => {
      // Get the first (and only) instance's revenue array
      const revenueArray = this.instances?.[0]?.['line-values'] as number[] || [];

      return {
        name: timeLabel,
        revenue: revenueArray[timeIndex] || 0
      };
    }) || [];

    return (
      <div style={{
        width: '100%',
        height: '100%',
        backgroundColor: this.globalParameters['background-color'] as string || '#ffffff',
        padding: '20px',
        fontFamily: 'sans-serif',
        boxSizing: 'border-box'
      }}>
        {this.globalParameters['show-title'] && (
          <h2 style={{
            textAlign: 'center',
            margin: '0 0 20px 0',
            fontSize: '24px',
            color: '#1f2937',
            fontWeight: 'bold'
          }}>
            {this.globalParameters['chart-title'] as string || 'Quarterly Revenue 2024'}
          </h2>
        )}

        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
          >
            {this.globalParameters['show-grid'] && (
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
            )}

            <XAxis 
              dataKey="name" 
              stroke="#6b7280"
              label={{ value: 'Quarter', position: 'insideBottom', offset: -5 }}
            />

            <YAxis 
              stroke="#6b7280"
              label={{ value: 'Revenue (USD)', angle: -90, position: 'insideLeft' }}
            />

            {this.globalParameters['show-tooltip'] && (
              <Tooltip 
                formatter={(value: number) => `$${value.toLocaleString()}`}
                labelFormatter={(label) => `Quarter: ${label}`}
              />
            )}

            {this.globalParameters['show-legend'] && <Legend />}

            <Line
              type={this.globalParameters['smooth-curve'] ? 'monotone' : 'linear'}
              dataKey="revenue"
              stroke={this.globalParameters['line-color'] as string || '#3b82f6'}
              strokeWidth={this.globalParameters['stroke-width'] as number || 2}
              dot={this.globalParameters['show-dots']}
              name="Revenue"
              activeDot={{ r: 8 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    );
  }
}

